{
  "title": "The Rescue at Ashen Hold",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue party studies a map of the fallen city.",
      "visual_description": "Four travelers crouched under a windblown oak at dusk, a worn parchment map spread across a flat stone, the ruined skyline of a royal city visible on the horizon.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden"]
    },
    {
      "scene_number": 2,
      "caption": "Brindle scouts the broken castle gates.",
      "visual_description": "A hooded scout pressed against a shattered portcullis, twin iron gates hanging off their hinges, moonlight cutting through cracks in the stonework.",
      "characters": ["Brindle the Scout"]
    },
    {
      "scene_number": 3,
      "caption": "The party slips into the outer courtyard.",
      "visual_description": "Four figures creeping past toppled statues and weed-choked flagstones, faded royal banners drooping from a broken archway above them.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden"]
    },
    {
      "scene_number": 4,
      "caption": "A frightened townswoman warns of patrols.",
      "visual_description": "A thin woman in a soot-stained shawl pulling Sir Halden into a doorway, lantern light catching the fear on her face, a cracked fountain behind them.",
      "characters": ["Sir Halden", "Goodwife Talla"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march down the avenue.",
      "visual_description": "A column of black-plated soldiers with spears, their boots kicking up ash on a long ruined boulevard lined with broken columns, the party hidden behind a collapsed cart.",
      "characters": ["Brindle the Scout", "Sir Halden", "Captain Vorr"]
    },
    {
      "scene_number": 6,
      "caption": "Ovic distracts the patrol with a flickering illusion.",
      "visual_description": "A spellwright in patchwork robes flicking glowing sparks down a side alley, a shimmering phantom deer bounding away while the patrol turns to chase.",
      "characters": ["Ovic the Spellwright", "Captain Vorr"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon stir in the smoke.",
      "visual_description": "The party staring up at a distant plume of red smoke curling above a jagged tower, embers drifting like snow over the rooftops.",
      "characters": ["Maren the Cartographer", "Ovic the Spellwright", "Sir Halden"]
    },
    {
      "scene_number": 8,
      "caption": "Maren refuses to detour for the dragon's hoard.",
      "visual_description": "The cartographer firmly rolling up the map and pointing toward a distant spire, Brindle smirking with arms folded, ruined chapel walls behind them.",
      "characters": ["Maren the Cartographer", "Brindle the Scout"]
    },
    {
      "scene_number": 9,
      "caption": "They pass beneath the cursed tower.",
      "visual_description": "A leaning black tower wrapped in greenish runes, the party tiptoeing along its shadow, faint whispering faces pressed against the stones.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden"]
    },
    {
      "scene_number": 10,
      "caption": "A sleepy gate-warden blocks the inner ward.",
      "visual_description": "A plump official in a too-large tabard yawning on a stool before a studded oak door, keys dangling from his belt, half-eaten pie beside him.",
      "characters": ["Warden Pibble", "Sir Halden"]
    },
    {
      "scene_number": 11,
      "caption": "Ovic charms the warden into snoring sleep.",
      "visual_description": "The spellwright humming with glowing fingertips over the warden's head, the warden slumping happily against the door, keys slipping into Brindle's waiting hand.",
      "characters": ["Ovic the Spellwright", "Brindle the Scout", "Warden Pibble"]
    },
    {
      "scene_number": 12,
      "caption": "They face a sealed magic door.",
      "visual_description": "A tall silver door etched with concentric runes, faint blue light pulsing from its seams, the four party members studying its glyphs by torchlight.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden"]
    },
    {
      "scene_number": 13,
      "caption": "Ovic unravels the door's sigil.",
      "visual_description": "Glowing runes peeling away like petals under the spellwright's tracing fingers, blue light washing over the party's awed faces.",
      "characters": ["Ovic the Spellwright", "Maren the Cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "They find Princess Ilsa chained in the throne room.",
      "visual_description": "A young woman in a torn green gown shackled to the foot of a cracked stone throne, dust motes drifting in shafts of pale light through broken stained glass.",
      "characters": ["Princess Ilsa", "Sir Halden", "Ovic the Spellwright"]
    },
    {
      "scene_number": 15,
      "caption": "Sir Halden cuts her chains as patrols close in.",
      "visual_description": "A knight swinging a glowing blade down on iron shackles, sparks flying, shadows of armored soldiers lengthening across the throne room floor.",
      "characters": ["Sir Halden", "Princess Ilsa", "Captain Vorr"]
    },
    {
      "scene_number": 16,
      "caption": "A running chase through the burning market.",
      "visual_description": "The party sprinting past overturned stalls and flapping royal banners, Captain Vorr's soldiers in pursuit, sparks raining from a collapsing rooftop.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden", "Princess Ilsa", "Captain Vorr"]
    },
    {
      "scene_number": 17,
      "caption": "Brindle leaps the gap of the crumbling bridge.",
      "visual_description": "The scout vaulting across a missing span of an old stone bridge over a foggy chasm, a rope uncoiling behind her, the rest of the party watching tensely from the near side.",
      "characters": ["Brindle the Scout", "Princess Ilsa", "Sir Halden", "Ovic the Spellwright", "Maren the Cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge as dawn breaks.",
      "visual_description": "The party walking single-file across a swaying rope-and-plank span, the ruined city silhouetted against a pink-gold sunrise behind them, Captain Vorr glaring helplessly from the far gate.",
      "characters": ["Maren the Cartographer", "Brindle the Scout", "Ovic the Spellwright", "Sir Halden", "Princess Ilsa", "Captain Vorr"]
    }
  ]
}

